/bin/bash -lc "python - <<'PY'
import json
j=json.load(open('/workspace/run_trace/compute_tool.json'))
# print input names tree
def walk(inputs, prefix=''):
    for inp in inputs:
        print(prefix+inp.get('type','?'), inp.get('name'), 'value=', inp.get('value'))
        if inp.get('type')=='conditional':
            for case in inp['cases']:
                print(prefix+' CASE', inp['name'], 'value', case['value'])
                walk(case.get('inputs',[]), prefix+'  ')
        elif inp.get('type')=='repeat':
            walk(inp.get('inputs',[]), prefix+'  ')
        elif inp.get('type')=='section':
            walk(inp.get('inputs',[]), prefix+'  ')
walk(j['inputs'])
PY"
